  [2943] = { "Il prossimo attacco in mischia contro l'incantatore infligge $N1 danni da ombra e riduce la potenza d'attacco in mischia dell'attaccante di $N2 per $D1.", "Potenza d'attacco in mischia ridotta di $N1.", 0xe28190de, 0x100ea149, "uu" },
