  [2947] = { "Circonda il bersaglio con uno scudo di fuoco. Ogni colpo inferto al bersaglio infligge $N1 danni da fuoco all'attaccante. Dura $D1. Il tuo famiglio non può lanciare ⟦Fire Shield=Scudo di Fuoco⟧ su se stesso.", "Infligge $N1 danni da fuoco all'attaccante quando viene colpito.", 0x9dc0d206, 0x8a7fa492, "uu" },
